@push('styles')
<style>
.doc-workspace .note{overflow-wrap:anywhere}.doc-workspace .final-issues{max-height:540px;overflow:auto}
.doc-workspace .selection-workspace{min-width:0}.doc-workspace .selection-workspace>*{min-width:0}.doc-workspace .selection-workspace:has(#candidate-review:not([hidden])){display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}.doc-workspace .selection-footer{position:sticky;bottom:-18px;background:var(--card-bg,#fff);padding:14px 0;border-top:1px solid var(--border-color,#ddd);z-index:2}.doc-workspace #add-documents>.doc-toolbar{position:sticky;top:-18px;background:var(--card-bg,#fff);padding:10px 0;z-index:2}.doc-workspace #candidate-review{padding-top:16px}
@media(max-width:900px){.doc-workspace .selection-workspace:has(#candidate-review:not([hidden])){grid-template-columns:1fr}}
.doc-workspace .document-result .actions{flex-shrink:0}.doc-workspace #candidate-preview{height:50vh;min-height:260px}
.doc-workspace [hidden]{display:none!important}
.doc-workspace{width:100%;max-width:none;min-width:0;color:var(--text-primary,#17243b)}.doc-workspace *{box-sizing:border-box}.doc-workspace .panel{margin:16px 0;padding:22px}.doc-workspace h2{font-size:20px;line-height:1.35}.doc-workspace h3{font-size:16px;line-height:1.4}.doc-workspace p{line-height:1.55}.doc-workspace .muted{color:var(--text-muted,#64748b);font-size:13px}.doc-workspace .cta{display:inline-flex;align-items:center;justify-content:center;min-height:42px;text-decoration:none;font-weight:600}.doc-workspace .cta:disabled{opacity:.45;cursor:not-allowed}.doc-workspace .doc-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.doc-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 20px;border-bottom:1px solid var(--border-color,#ddd);padding-bottom:10px}.doc-tabs a{padding:8px 14px;border-radius:8px;text-decoration:none;color:var(--text-primary,#17243b);font-size:13px}.doc-tabs a[aria-current=page]{background:#233f88;color:#fff;font-weight:600}.doc-workspace .doc-counts{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.doc-workspace .doc-counts a{border:1px solid var(--border-color,#ddd);background:var(--card-bg,#fff);border-radius:10px;padding:12px 18px;color:inherit;text-decoration:none;font-size:13px}.doc-workspace .doc-counts strong{font-size:20px;margin-right:8px}.doc-workspace .doc-card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,340px),1fr));gap:16px}.doc-workspace .doc-card{display:flex;flex-direction:column;min-width:0;background:var(--card-bg,#fff);border:1px solid var(--border-color,#ddd);border-radius:14px;padding:20px;gap:12px}.doc-workspace .doc-card h2{font-size:17px;overflow-wrap:anywhere}.doc-workspace .doc-card footer{margin-top:auto}.doc-workspace .doc-state{display:inline-flex;align-items:center;border-radius:6px;padding:4px 8px;font-size:12px;font-weight:600;background:var(--hover-bg,#eef2f8);color:var(--text-primary,#17243b)}.doc-workspace .doc-state.BORRADOR{background:#fff3d8;color:#805200}.doc-workspace .doc-state.ACTIVA{background:#e6f5ec;color:#19623d}.doc-workspace .doc-card ul{list-style:none;padding:0;margin:0;font-size:12px;color:var(--text-muted,#64748b)}.doc-workspace .doc-card li{padding:4px 0;overflow-wrap:anywhere}.doc-workspace progress{width:100%;height:7px;accent-color:#227448}.doc-workspace .doc-empty{padding:40px 24px;text-align:center;background:var(--card-bg,#fff);border:1px dashed var(--border-color,#ddd);border-radius:14px}.doc-workspace .doc-empty .actions{justify-content:center;margin-top:18px}.doc-workspace .doc-filter{display:grid;grid-template-columns:minmax(160px,1fr) minmax(150px,220px) auto;gap:12px;align-items:end}.doc-workspace label{line-height:1.5}.doc-workspace label :is(input,select){margin-top:5px}.doc-workspace :focus-visible{outline:3px solid #458bef;outline-offset:3px}.doc-workspace .doc-review-grid{display:grid;grid-template-columns:minmax(270px,.8fr) minmax(0,1.8fr);gap:18px;align-items:start}.doc-workspace .doc-review-grid>.panel{min-width:0;margin:0}.doc-workspace .doc-list{list-style:none;padding:0;margin:12px 0;max-height:650px;overflow:auto}.doc-workspace .doc-list li{border-bottom:1px solid var(--border-color,#ddd)}.doc-workspace .doc-list a{display:block;padding:14px 12px;text-decoration:none;color:inherit;border-left:3px solid transparent;overflow-wrap:anywhere;font-size:13px}.doc-workspace .doc-list a[aria-current=true]{background:var(--hover-bg,#f0f4fc);border-left-color:#315dd1}.doc-workspace .doc-list small{display:block;margin-top:5px;color:var(--text-muted,#64748b)}.doc-workspace .doc-review-title{margin-top:16px;overflow-wrap:anywhere;font-size:16px}.doc-workspace .pdf-frame{width:100%;height:62vh;min-height:380px;border:1px solid var(--border-color,#ddd);border-radius:8px;background:#f4f5f7}.doc-workspace .doc-review-status{padding:9px 0;font-size:12px;color:var(--text-muted,#64748b)}.doc-workspace .doc-confirm{padding:16px 0 0;margin-top:12px;border-top:1px solid var(--border-color,#ddd)}.doc-workspace .doc-confirm button{margin-top:12px}.doc-workspace .doc-danger{color:#b32626;background:transparent;border:1px solid #dc8e8e}.doc-workspace .doc-version-links{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}.doc-workspace dialog{width:min(96vw,1500px);max-width:96vw;height:94vh;max-height:94vh;margin:auto;border:1px solid var(--border-color,#ddd);border-radius:14px;padding:18px;background:var(--card-bg,#fff);color:inherit}.doc-workspace dialog::backdrop{background:rgba(10,20,35,.65)}.doc-workspace dialog .pdf-frame{height:calc(94vh - 100px)}.doc-workspace .doc-reference-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:14px;padding:12px 0;border-top:1px solid var(--border-color,#ddd);font-size:13px;overflow-wrap:anywhere}.dark-mode .doc-workspace .doc-danger{color:#ffb5b5}.doc-workspace .doc-field-hint{font-size:12px;color:var(--text-muted,#64748b);margin:8px 0}
@media(max-width:1000px){.doc-workspace .doc-review-grid{grid-template-columns:1fr}.doc-workspace .doc-list{max-height:260px}.doc-workspace .doc-filter{grid-template-columns:1fr 1fr}.doc-workspace .doc-filter>label:first-child{grid-column:1/-1}}
@media(max-width:600px){.doc-workspace .document-result{align-items:flex-start;flex-direction:column}.doc-workspace .document-result .actions{width:100%}.doc-workspace .panel{padding:16px}.doc-workspace .doc-filter,.doc-workspace .fields{grid-template-columns:1fr}.doc-workspace .doc-toolbar{align-items:flex-start}.doc-workspace .cta{min-height:44px}.doc-workspace .doc-reference-row{grid-template-columns:1fr}.doc-workspace .pdf-frame{height:52vh;min-height:320px}.doc-workspace .doc-counts{gap:8px}.doc-workspace .doc-counts a{padding:10px 12px}}

.doc-workspace .doc-parent-choices {display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:12px;max-height:320px;overflow:auto;padding:8px;}
.doc-workspace .doc-parent-choices .check {align-items:flex-start;border:1px solid #dbe2ef;border-radius:10px;padding:12px;min-width:0;}
.doc-workspace .doc-parent-choices small {display:block;color:#64748b;margin-top:4px;overflow-wrap:anywhere;}
.doc-workspace .doc-composition-fields {margin:20px 0;}
.doc-workspace .doc-composition-fields fieldset {min-width:0;border:1px solid #dbe2ef;border-radius:12px;padding:16px;}
.doc-workspace .doc-source-chain {display:flex;flex-wrap:wrap;gap:8px;margin:16px 0;}
.doc-workspace .doc-source-chain a {white-space:normal;overflow-wrap:anywhere;max-width:100%;}
.doc-workspace .doc-inherited-list {max-height:360px;overflow:auto;}
.doc-workspace .doc-counts>div {padding:12px;min-width:0;}
.doc-workspace .doc-counts>div strong {display:block;font-size:1.35rem;}

.doc-workspace .doc-validation-badge{display:inline-flex;align-items:center;gap:6px;max-width:100%;padding:4px 8px;margin:6px 0;border-radius:7px;font-size:12px;line-height:1.4;font-weight:600;border:1px solid transparent;white-space:normal}
.doc-workspace .doc-validation-icon{display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;flex:0 0 18px;border-radius:50%;font-size:14px;font-weight:800;background:currentColor}
.doc-workspace .doc-validation-icon{background:transparent;border:1.5px solid currentColor}
.doc-workspace .doc-validation-validados{color:#166534;background:#dcfce7;border-color:#86efac}
.doc-workspace .doc-validation-observados{color:#9a3412;background:#fff7ed;border-color:#fdba74}
.doc-workspace .doc-validation-por-revisar{color:#854d0e;background:#fef9c3;border-color:#fde047}
.doc-workspace .doc-validation-sin-vincular{color:#475569;background:#f1f5f9;border-color:#cbd5e1}
.doc-workspace .doc-list a>strong{display:block}
.dark-mode .doc-workspace .doc-validation-validados{color:#bbf7d0;background:#14532d;border-color:#22c55e}
.dark-mode .doc-workspace .doc-validation-observados{color:#fed7aa;background:#7c2d12;border-color:#fb923c}
.dark-mode .doc-workspace .doc-validation-por-revisar{color:#fef08a;background:#713f12;border-color:#eab308}
.dark-mode .doc-workspace .doc-validation-sin-vincular{color:#e2e8f0;background:#334155;border-color:#94a3b8}
.doc-workspace .doc-validation-action{padding:14px;margin:12px 0 16px;border:1px solid var(--border-color,#cbd5e1);border-radius:10px;background:var(--hover-bg,#f8fafc)}
.doc-workspace .doc-validation-action h3{margin:0 0 6px}.doc-workspace .doc-validation-action .check{align-items:flex-start}.doc-workspace #document-correction{scroll-margin-top:24px}
</style>
@endpush
